/// <summary>
/// reviewLines' and postJournal's answer. ErrorCode: NOT_SUPERVISOR, JOURNAL_POSTED,
/// JOURNAL_NOT_FOUND, LINES_NEED_APPROVAL, RECOUNT_SAME_USER, POST_FAILED, NOT_IMPLEMENTED.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountSupervisorResponse
{
    boolean success;
    str     errorCode;
    str     message;
    int     affected;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('Affected')]
public int parmAffected(int _value = affected)
{
    affected = _value;
    return affected;
}
